#!/usr/bin/env bash
# Generated by Claude (Anthropic) on 2026-11-12, following directions from the script's owner:
#   - GNOME wallpaper changes by time of day (morning/afternoon/evening/night PNGs in WALLPAPER_DIR)
#   - Start hours are settable below in 24h format; each range ends where the next begins (night wraps past midnight)
#   - Daemon-style: wakes every CHECK_SECONDS, no hot loop, no state kept between checks
#   - Calls gsettings on every check, with no error handling beyond logging its exit code
#   - Logs every update to stdout (stderr if gsettings failed); log retention is left to the service manager
# Review before relying on it. Run it from your session (e.g. a systemd user service) so gsettings can reach D-Bus.

# Hour (24h) at which each wallpaper starts. Each range ends where the next begins; night wraps past midnight to morning.
MORNING=06 AFTERNOON=12 EVENING=14 NIGHT=20
WALLPAPER_DIR=~/Desktop/wallpapers
CHECK_SECONDS=1800
#CHECK_SECONDS=3

# background image file names
names=(morning afternoon evening2 night)

# gnomes theme names in the same order
themes=(Yaru\-blue Yaru\-dark Yaru\-red\-dark Yaru\-red\-dark)

# gnome color-scheme
schemes=(prefer\-light prefer\-light prefer\-dark prefer\-dark)

# 10# forces base 10, otherwise "06" or "08" is parsed as octal
starts=($((10#$MORNING)) $((10#$AFTERNOON)) $((10#$EVENING)) $((10#$NIGHT)))

printf '[%(%F %T)T] started: morning=%s afternoon=%s evening=%s night=%s, interval=%ss\n' -1 "$MORNING" "$AFTERNOON" "$EVENING" "$NIGHT" "$CHECK_SECONDS"

while true; do
  printf -v hour '%(%H)T' -1
  hour=$((10#$hour))

  for i in "${!names[@]}"; do
    lower=${starts[i]}
    upper=${starts[(i + 1) % ${#starts[@]}]}   # next range's start; last wraps to first
    # upper >= lower: same-day range [lower, upper). Otherwise it wraps past midnight: [lower, 24) + [0, upper)
    if (( upper >= lower )); then
      (( hour >= lower && hour < upper )) && in_range=1 || in_range=0
    else
      (( hour >= lower || hour < upper )) && in_range=1 || in_range=0
    fi
    if (( in_range )); then
      wallpaper="file://$WALLPAPER_DIR/${names[i]}.png"
	
      gsettings set org.gnome.desktop.background picture-uri "$wallpaper"
      status=$?
      printf '[%(%F %T)T] set picture-uri to %s (hour=%d, range %d..%d, file=%s) exit=%d\n' -1 "$wallpaper" "$hour" "$lower" "$upper" "$wallpaper" "$status" >&$((status ? 2 : 1))
      
      gsettings set org.gnome.desktop.background picture-uri-dark "$wallpaper"
      status=$?
      printf '[%(%F %T)T] set picture-uri-dark to  %s (hour=%d, range %d..%d, file=%s) exit=%d\n' -1 "$wallpaper" "$hour" "$lower" "$upper" "$wallpaper" "$status" >&$((status ? 2 : 1))
	
      theme="${themes[i]}"
      gsettings set org.gnome.desktop.interface gtk-theme "$theme"
      status=$?
      printf '[%(%F %T)T] set gtk-theme to %s (hour=%d, range %d..%d, file=%s) exit=%d\n' -1 "$theme" "$hour" "$lower" "$upper" "$wallpaper" "$status" >&$((status ? 2 : 1))

      scheme=$"${schemes[i]}"
      gsettings set org.gnome.desktop.interface color-scheme "$scheme"
      status=$?
      printf '[%(%F %T)T] set gtk-theme to %s (hour=%d, range %d..%d, file=%s) exit=%d\n' -1 "$scheme" "$hour" "$lower" "$upper" "$wallpaper" "$status" >&$((status ? 2 : 1))


      break
    fi
  done

  sleep "$CHECK_SECONDS"
done

